'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dorglq = require( './../lib' );

// Specify matrix meta data:
var shape = [ 3, 4 ];
var order = 'row-major';
var strides = shape2strides( shape, order );

// Create a matrix stored in linear memory:
var A = new Float64Array( [ 1.0, 0.0, 0.0, 0.0, -2.0, 1.0, 0.0, 0.0, -3.0, -4.0, 1.0, 0.0 ] ); // eslint-disable-line max-len
console.log( 'A (before):' );
console.log( ndarray2array( A, shape, strides, 0, order ) );

// Define the scalar factors of the elementary reflectors:
var TAU = new Float64Array( [ 1.0, 1.0, 1.0 ] );

// Allocate a workspace array:
var WORK = new Float64Array( 20 );

// Generate the orthogonal matrix Q:
var info = dorglq( order, shape[ 0 ], shape[ 1 ], shape[ 0 ], A, strides[ 0 ], TAU, WORK, 20 ); // eslint-disable-line max-len
console.log( 'Q (after):' );
console.log( ndarray2array( A, shape, strides, 0, order ) );
console.log( info );
